\set ON_ERROR_STOP on
update billing_rollout_flags set enforce_v2=true;
-- Test helper raises on failed assertions.
create function public.assert_true(v boolean,description text) returns void language plpgsql as $$begin if v is distinct from true then raise exception '%',description;end if;end$$;
set request.jwt.claim.sub='00000000-0000-0000-0000-000000000001';
select billing_like(('00000000-0000-0000-0000-'||lpad(i::text,12,'0'))::uuid) from generate_series(2,6) i;
select assert_true((billing_snapshot()->>'remaining')::int=0,'Five swipes exhaust allowance');
do $$begin perform billing_like('00000000-0000-0000-0000-000000000007');raise exception 'Sixth allowed';exception when others then if sqlerrm<>'DAILY_SWIPE_LIMIT' then raise;end if;end$$;
select billing_like('00000000-0000-0000-0000-000000000002');
select assert_true((select count(*)=5 from billing_swipe_usage),'Retry costs nothing');
do $$begin insert into app_item_state values(auth.uid(),'save','company-one');raise exception 'Shared allowance bypass';exception when others then if sqlerrm<>'DAILY_SWIPE_LIMIT' then raise;end if;end$$;
select billing_sync_subscription('sub-event','00000000-0000-0000-0000-000000000001','sub_test','active',now()+interval '1 month','month-1');
select billing_sync_subscription('sub-event-retry','00000000-0000-0000-0000-000000000001','sub_test','active',now()+interval '1 month','month-1');
select assert_true((select credits=1 from billing_wallets where user_id=auth.uid()),'Monthly credit only once');
select billing_like('00000000-0000-0000-0000-000000000007');
select billing_use_boost();
do $$begin perform billing_use_boost();raise exception 'Repeat boost allowed';exception when others then if sqlerrm not like 'Your next boost%' then raise;end if;end$$;
select assert_true((select count(*)=1 from billing_boosted_profiles()),'Boost discoverable');
select billing_send_instant('00000000-0000-0000-0000-000000000008','Hello','00000000-0000-0000-0000-000000000020');
select billing_send_instant('00000000-0000-0000-0000-000000000008','Hello','00000000-0000-0000-0000-000000000020');
select assert_true((select credits=0 from billing_wallets where user_id=auth.uid()),'Send retry not double charged');
select assert_true((select count(*)=1 from messages),'One message on retry');
select assert_true((select count(*)=1 from matches),'Instant creates match');
do $$begin perform billing_send_instant('00000000-0000-0000-0000-000000000009','Hello','00000000-0000-0000-0000-000000000021');raise exception 'Free instant allowed';exception when others then if sqlerrm<>'NO_MESSAGE_CREDITS' then raise;end if;end$$;
insert into billing_orders(id,user_id,sku,amount,stripe_session_id) values('00000000-0000-0000-0000-000000000030',auth.uid(),'messages_three',2500,'cs_test');
select billing_apply_purchase('purchase','00000000-0000-0000-0000-000000000030','cs_test',2500,'usd');
select billing_apply_purchase('purchase-retry','00000000-0000-0000-0000-000000000030','cs_test',2500,'usd');
select assert_true((select credits=3 from billing_wallets where user_id=auth.uid()),'Pack credit once');
insert into billing_orders(id,user_id,sku,amount,stripe_session_id) values('00000000-0000-0000-0000-000000000031',auth.uid(),'messages_six',3500,'cs_test_bad');
do $$begin perform billing_apply_purchase('bad-event','00000000-0000-0000-0000-000000000031','cs_test_bad',100,'usd');raise exception 'Amount bypass';exception when others then if sqlerrm<>'Payment does not match order' then raise;end if;end$$;
select assert_true(not exists(select 1 from billing_events where event_id='bad-event'),'Invalid fulfillment rolls back event');
set request.jwt.claim.sub='00000000-0000-0000-0000-000000000002';
select billing_like('00000000-0000-0000-0000-000000000001');
select assert_true((select count(*)=2 from matches),'Mutual like match');
set role authenticated;
select assert_true((select count(*)=1 from swipes),'Free incoming likes hidden');
do $$begin insert into matches(user_1_id,user_2_id) values(auth.uid(),'00000000-0000-0000-0000-000000000040');raise exception 'Unsolicited match bypass';exception when insufficient_privilege then null;end$$;
do $$begin insert into messages(sender_id,receiver_id,content) values(auth.uid(),'00000000-0000-0000-0000-000000000040','bad');raise exception 'Unsolicited message bypass';exception when insufficient_privilege then null;end$$;
do $$begin perform billing_sync_subscription('evil',auth.uid(),'evil','active',now()+interval '1 year','evil');raise exception 'Client can mint Pro';exception when insufficient_privilege then null;end$$;
reset role;
select 'billing database assertions passed';

set request.jwt.claim.sub='00000000-0000-0000-0000-000000000050';
select billing_sync_subscription('annual-start',auth.uid(),'sub_annual','active',now()+interval '10 months','annual-1','year',now()-interval '2 months 1 day');
select assert_true((billing_snapshot()->>'credits')::int=3,'Annual earns one credit per elapsed month');
select billing_sync_subscription('annual-retry',auth.uid(),'sub_annual','active',now()+interval '10 months','annual-1','year',now()-interval '2 months 1 day');
select assert_true((billing_snapshot()->>'credits')::int=3,'Annual retries and snapshots do not mint credits');
select billing_sync_subscription('annual-unpaid-update',auth.uid(),'sub_annual','past_due',now()+interval '10 months',null,'year',now()-interval '4 months');
select assert_true((billing_snapshot()->>'credits')::int=3,'Unpaid annual state cannot accrue credits');
set role authenticated;
do $$begin perform billing_accrue_annual(auth.uid());raise exception 'Client can accrue arbitrary credits';exception when insufficient_privilege then null;end$$;
reset role;
select 'annual credit assertions passed';
